<?php
declare(strict_types=1);
return static function(PDO $pdo):void{
    $pdo->exec("CREATE TABLE program_manuals (id INT AUTO_INCREMENT PRIMARY KEY,program_specification_id INT NOT NULL,title VARCHAR(255) NOT NULL,version_label VARCHAR(100) NOT NULL,academic_period VARCHAR(50) NULL,status ENUM('Draft','Under Review','Approved','Archived') NOT NULL DEFAULT 'Draft',prepared_by VARCHAR(255) NULL,approved_by VARCHAR(255) NULL,updated_date DATE NULL,approval_date DATE NULL,next_review_date DATE NULL,source_original_name VARCHAR(255) NULL,source_storage_key VARCHAR(500) NULL,source_sha256 CHAR(64) NULL,source_mime VARCHAR(100) NULL,source_size BIGINT UNSIGNED NULL,created_by_user_id INT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_program_manual_version(program_specification_id,version_label),KEY idx_program_manual_status(status),KEY idx_program_manual_review(next_review_date),CONSTRAINT fk_program_manual_program FOREIGN KEY(program_specification_id) REFERENCES program_specifications(id) ON DELETE CASCADE,CONSTRAINT fk_program_manual_creator FOREIGN KEY(created_by_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE program_manual_sections (id INT AUTO_INCREMENT PRIMARY KEY,program_manual_id INT NOT NULL,section_key VARCHAR(100) NOT NULL,heading VARCHAR(255) NOT NULL,content LONGTEXT NULL,sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_program_manual_section(program_manual_id,section_key),KEY idx_program_manual_section_order(program_manual_id,sort_order),CONSTRAINT fk_program_manual_section_manual FOREIGN KEY(program_manual_id) REFERENCES program_manuals(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
};
